1	import { useState, useEffect, useMemo } from "react";
2	import { useSearch, useLocation } from "wouter";
3	import { useQuery } from "@tanstack/react-query";
4	import { Layout } from "@/components/layout";
5	import { useListCourts, useListCities } from "@workspace/api-client-react";
6	import { CourtCard } from "@/components/court-card";
7	import { CourtMap } from "@/components/court-map";
