22	const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
23	const API = `${BASE}/api`;
24	
25	function makeTimeSlots(from = "07:00", to = "22:00") {
26	  const slots: string[] = [];
27	  const [fh, fm] = from.split(":").map(Number);
28	  const [th, tm] = to.split(":").map(Number);
29	  let cur = fh * 60 + fm;
30	  const end = th * 60 + tm;
31	  while (cur < end) {
32	    slots.push(`${String(Math.floor(cur / 60)).padStart(2, "0")}:${String(cur % 60).padStart(2, "0")}`);
33	    cur += 30;
34	  }
35	  return slots;
36	}
37	const TIME_SLOTS = makeTimeSlots();
38	const DURATION_OPTIONS = [
39	  { label: "30 min", value: 30 },
40	  { label: "1 val.", value: 60 },
41	  { label: "1.5 val.", value: 90 },
42	  { label: "2 val.", value: 120 },
43	  { label: "2.5 val.", value: 150 },
44	  { label: "3 val.", value: 180 },
45	];
46	
47	function addMins(t: string, mins: number): string {
48	  const [h, m] = t.split(":").map(Number);
49	  const total = h * 60 + m + mins;
50	  return `${String(Math.floor(total / 60)).padStart(2, "0")}:${String(total % 60).padStart(2, "0")}`;
51	}
52	
53	type ViewMode = "list" | "map";
54	
55	const PAGE_SIZE = 12;
56	
57	const NEARBY_KM = 30;
58	
59	function haversineKm(lat1: number, lng1: number, lat2: number, lng2: number): number {
60	  const R = 6371;
61	  const dLat = ((lat2 - lat1) * Math.PI) / 180;
62	  const dLng = ((lng2 - lng1) * Math.PI) / 180;
63	  const a =
64	    Math.sin(dLat / 2) ** 2 +
65	    Math.cos((lat1 * Math.PI) / 180) * Math.cos((lat2 * Math.PI) / 180) * Math.sin(dLng / 2) ** 2;
66	  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
67	}
68	
69	const surfaceKeys = ["clay", "hard", "carpet", "synthetic_grass", "artificial_grass", "natural_grass", "parquet", "rubber"] as const;
70	
71	const HERO_IMAGES = [
72	  "courts/court_2_bernardinu",
73	  "courts/padel/padel_court_indoor_1",
74	  "courts/court_17_zalgiris",
75	  "courts/football/football_futsal_court_2",
76	  "courts/badminton/badminton_court_indoor_1",
77	  "courts/squash/squash_court_1",
78	  "courts/court_4_verkiai",
79	  "courts/padel/padel_court_indoor_3",
80	  "courts/court_3_lsc_vingis",
81	  "courts/court_1_seb_arena",
82	];
83	
84	export default function Courts() {
85	  const t = useT();
86	  const searchStr = useSearch();
87	  const [, setLocation] = useLocation();
88	  const _qp = new URLSearchParams(searchStr.replace(/^\?/, ""));
89	  const initialType = (_qp.get("type") as ListCourtsType | null) ?? null;
90	  const initialName = _qp.get("name") ?? "";
91	  const initialCity = _qp.get("city") ?? "";
92	  const linkGameId = _qp.get("linkGameId") ? parseInt(_qp.get("linkGameId")!) : null;
93	
94	  const ALL_SPORTS = ["tennis", "basketball", "padel", "football", "badminton", "squash", "table_tennis", "golf", "snooker", "bowling"];
95	  const sportLT: Record<string, string> = {
96	    tennis: "Tenisas", basketball: "Krepšinis", padel: "Padelis",
97	    table_tennis: "Stalo tenisas", golf: "Golfas", snooker: "Snukeris", bowling: "Boulingas",
98	    football: "Futbolas", badminton: "Badmintonas", squash: "Skvoše",
99	  };
100	
101	  const [search, setSearch] = useState(initialName);
102	  const [selectedCities, setSelectedCities] = useState<Set<string>>(initialCity ? new Set([initialCity]) : new Set());
103	  const [surface, setSurface] = useState<string>("all");
104	  const [isIndoorFilter, setIsIndoorFilter] = useState<"all" | "indoor" | "outdoor">("all");
105	  const [maxPrice, setMaxPrice] = useState<number>(100);
106	  const [sortBy, setSortBy] = useState<"default" | "price_asc" | "price_desc" | "rating_desc" | "favorites_first">("default");
107	  const { favoriteIds } = useFavoritesContext();
108	  const [viewMode, setViewMode] = useState<ViewMode>("list");
109	  const [mobileFiltersOpen, setMobileFiltersOpen] = useState(false);
110	  const [bgIdx, setBgIdx] = useState(0);
111	  const [cityExpanded, setCityExpanded] = useState(false);
112	  const [nearbyMode, setNearbyMode] = useState(false);
113	  const [nearbyLoading, setNearbyLoading] = useState(false);
114	  const [nearbyError, setNearbyError] = useState<string | null>(null);
115	  const [userLocation, setUserLocation] = useState<{ lat: number; lng: number } | null>(null);
116	
117	  // ── Link-game mode (booking a court for an existing match) ──────────────────
118	  const [linkDate, setLinkDate] = useState<string>(() => {
119	    const urlDate = _qp.get("date") ?? "";
120	    if (urlDate) return urlDate;
121	    try { return sessionStorage.getItem("linkGameDate") ?? ""; } catch { return ""; }
122	  });
123	  const [linkStartTime, setLinkStartTime] = useState<string>("");
124	  const [linkDurationMins, setLinkDurationMins] = useState(60);
125	  const linkEndTime = useMemo(() => linkStartTime ? addMins(linkStartTime, linkDurationMins) : "", [linkStartTime, linkDurationMins]);
126	
127	  const { data: gameData } = useQuery<{ id: number; sport: string; datetime: string; durationMinutes: number; city: string }>({
128	    queryKey: ["game-for-link", linkGameId],
129	    queryFn: async () => {
130	      const r = await fetch(`${API}/games/${linkGameId}`);
131	      if (!r.ok) throw new Error("Not found");
132	      return r.json();
133	    },
134	    enabled: !!linkGameId,
135	    staleTime: 60_000,
136	  });
137	
138	  useEffect(() => {
139	    if (!gameData) return;
140	    if (!linkDate) {
141	      const dt = new Date(gameData.datetime);
142	      setLinkDate(`${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, "0")}-${String(dt.getDate()).padStart(2, "0")}`);
143	    }
144	    // Do not auto-set start time — user picks freely within the date
145	  }, [gameData]);
146	
147	  useEffect(() => {
148	    if (!linkGameId) return;
149	    try {
150	      sessionStorage.setItem("linkGameId", String(linkGameId));
151	      if (linkDate) sessionStorage.setItem("linkGameDate", linkDate);
152	      if (linkStartTime) sessionStorage.setItem("linkGameStartTime", linkStartTime);
153	      if (linkEndTime) sessionStorage.setItem("linkGameEndTime", linkEndTime);
154	    } catch { /* ignore */ }
155	  }, [linkGameId, linkDate, linkStartTime, linkEndTime]);
156	
157	  const { data: availData, isLoading: availLoading } = useQuery<{ availableCourtIds: number[] }>({
158	    queryKey: ["courts-avail-for-slot", linkDate, linkStartTime, linkEndTime],
159	    queryFn: async () => {
160	      const p = new URLSearchParams({ date: linkDate, startTime: linkStartTime, endTime: linkEndTime });
161	      if (gameData?.sport) p.set("sport", gameData.sport);
162	      const r = await fetch(`${API}/courts/available-for-slot?${p}`);
163	      if (!r.ok) throw new Error("Failed");
164	      return r.json();
165	    },
166	    enabled: !!linkGameId && !!linkDate && !!linkStartTime && !!linkEndTime,
167	    staleTime: 30_000,
168	  });
169	
170	  const availableIdSet = availData ? new Set(availData.availableCourtIds) : null;
171	
172	  const handleNearbyList = () => {
173	    if (nearbyMode) {
174	      setNearbyMode(false);
175	      setUserLocation(null);
176	      setNearbyError(null);
177	      return;
178	    }
179	    if (!navigator.geolocation) {
180	      setNearbyError("Jūsų naršyklė nepalaiko geolokacijos.");
181	      return;
182	    }
183	    setNearbyLoading(true);
184	    setNearbyError(null);
185	    navigator.geolocation.getCurrentPosition(
186	      (pos) => {
187	        setUserLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
188	        setNearbyMode(true);
189	        setNearbyLoading(false);
190	      },
191	      (err) => {
192	        setNearbyLoading(false);
193	        setNearbyError(err.code === 1 ? "Leiskite prieigą prie vietos." : "Nepavyko nustatyti vietos.");
194	      },
195	      { timeout: 8000, maximumAge: 60000 }
196	    );
197	  };
198	
199	  useEffect(() => {
200	    const id = setInterval(() => setBgIdx(i => (i + 1) % HERO_IMAGES.length), 5000);
201	    return () => clearInterval(id);
202	  }, []);
203	
204	  const base = import.meta.env.BASE_URL.replace(/\/$/, "");
205	  const [page, setPage] = useState(1);
206	  const [activeSports, setActiveSports] = useState<Set<string>>(
207	    initialType && ALL_SPORTS.includes(initialType) ? new Set([initialType]) : new Set(ALL_SPORTS)
208	  );
209	
210	  const toggleSport = (sport: string) => {
211	    setActiveSports(prev => {
212	      const next = new Set(prev);
213	      if (next.has(sport)) {
214	        next.delete(sport);
215	      } else {
216	        next.add(sport);
217	      }
218	      return next;
219	    });
220	  };
221	  const allSportsActive = activeSports.size === ALL_SPORTS.length;
222	
223	  const toggleCity = (c: string) => {
224	    setSelectedCities(prev => {
225	      const next = new Set(prev);
226	      if (next.has(c)) next.delete(c); else next.add(c);
227	      return next;
228	    });
229	  };
230	
231	  useEffect(() => {
232	    setPage(1);
233	  }, [search, selectedCities, surface, isIndoorFilter, maxPrice, sortBy, activeSports]);
234	
235	  const { data: cities } = useListCities();
236	
237	  const querySurface = surface === "all" ? undefined : surface;
238	  const queryIsIndoor = isIndoorFilter === "all" ? undefined : isIndoorFilter === "indoor";
239	
240	  const { data: courts, isLoading } = useListCourts({
241	    surface: querySurface,
242	    isIndoor: queryIsIndoor,
243	    maxPrice,
244	  });
245	
246	  // Sort cities by court count descending
247	  const cityCounts = (courts ?? []).reduce<Record<string, number>>((acc, c) => {
248	    if (c.city) acc[c.city] = (acc[c.city] ?? 0) + 1;
249	    return acc;
250	  }, {});
251	  const sortedCities = (cities ?? []).slice().sort((a, b) => (cityCounts[b] ?? 0) - (cityCounts[a] ?? 0));
252	
253	  const filteredCourts = courts?.filter(c => {
254	    const matchesSearch =
255	      c.name.toLowerCase().includes(search.toLowerCase()) ||
256	      (c.city ?? "").toLowerCase().includes(search.toLowerCase()) ||
257	      (c.address ?? "").toLowerCase().includes(search.toLowerCase());
258	    const matchesCity = selectedCities.size === 0 || (!!c.city && selectedCities.has(c.city));
259	    const matchesNearby = !nearbyMode || !userLocation || (c.latitude != null && c.longitude != null && haversineKm(userLocation.lat, userLocation.lng, c.latitude, c.longitude) <= NEARBY_KM);
260	    return matchesSearch && matchesCity && matchesNearby;
261	  });
262	
263	  const sortedCourts = filteredCourts ? [...filteredCourts]
264	    .filter(c => activeSports.has(c.type))
265	    .filter(c => !availableIdSet || availableIdSet.has(c.id))
266	    .sort((a, b) => {
267	      if (sortBy === "favorites_first") {
268	        const aFav = favoriteIds.has(a.id) ? 0 : 1;
269	        const bFav = favoriteIds.has(b.id) ? 0 : 1;
270	        return aFav - bFav;
271	      }
272	      if (sortBy === "rating_desc") return (b.rating ?? 0) - (a.rating ?? 0);
273	      if (sortBy === "price_asc") return a.pricePerHour - b.pricePerHour;
274	      if (sortBy === "price_desc") return b.pricePerHour - a.pricePerHour;
275	      return 0;
276	    }) : filteredCourts;
277	
278	  const totalCourts = sortedCourts?.length ?? 0;
279	  const totalPages = Math.max(1, Math.ceil(totalCourts / PAGE_SIZE));
280	  const pagedCourts = sortedCourts?.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);
281	
282	  const activeFilterCount = [
283	    selectedCities.size > 0,
284	    surface !== "all",
285	    isIndoorFilter !== "all",
286	    maxPrice < 100,
287	    activeSports.size < ALL_SPORTS.length,
288	    nearbyMode,
289	  ].filter(Boolean).length;
290	
291	  const resetFilters = () => {
292	    setSelectedCities(new Set());
293	    setSurface("all");
294	    setIsIndoorFilter("all");
295	    setMaxPrice(100);
296	    setSearch("");
297	    setSortBy("default");
298	    setActiveSports(new Set(ALL_SPORTS));
299	    setNearbyMode(false);
300	    setUserLocation(null);
301	    setNearbyError(null);
302	  };
303	
304	  const sportFilterControls = (
305	    <div>
306	      <div className="flex items-center justify-between mb-2">
307	        <Label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Sporto šakos</Label>
308	        <button
309	          onClick={() => setActiveSports(allSportsActive ? new Set() : new Set(ALL_SPORTS))}
310	          className="text-[10px] font-medium text-primary hover:underline"
311	        >
312	          {allSportsActive ? "Slėpti viską" : "Rodyti viską"}
313	        </button>
314	      </div>
315	      <div className="space-y-1">
316	        {ALL_SPORTS.map(sport => {
317	          const active = activeSports.has(sport);
318	          const color = sportColor[sport];
319	          const count = (courts ?? []).filter(c => c.type === sport).length;
320	          return (
321	            <button
322	              key={sport}
323	              onClick={() => toggleSport(sport)}
324	              className={`w-full flex items-center gap-2.5 px-2 py-1.5 rounded-lg transition-all text-left text-sm ${
325	                active ? "bg-muted/60 hover:bg-muted" : "opacity-40 hover:opacity-70 hover:bg-muted/30"
326	              }`}
327	            >
328	              <div
329	                className="w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 transition-all"
330	                style={{ background: active ? color : "transparent", borderColor: color }}
331	              >
332	                <SportIcon sport={sport} size={11} strokeWidth={2} style={{ color: active ? "white" : color }} />
333	              </div>
334	              <span className={`flex-1 font-medium transition-colors ${active ? "text-foreground" : "text-muted-foreground"}`}>
335	                {sportLT[sport]}
336	              </span>
337	              <span className={`text-xs tabular-nums ${active ? "text-muted-foreground" : "text-muted-foreground/50"}`}>
338	                {count}
339	              </span>
340	            </button>
341	          );
342	        })}
343	      </div>
344	    </div>
345	  );
346	
347	  const filterControls = (
348	    <div className="space-y-6">
349	      {/* Nearby location button */}
350	      <div>
351	        <button
352	          onClick={handleNearbyList}
353	          disabled={nearbyLoading}
354	          className={`w-full flex items-center gap-2.5 px-3 py-2.5 rounded-xl border text-sm font-medium transition-all ${
355	            nearbyMode
356	              ? "bg-primary text-primary-foreground border-primary"
357	              : "border-border bg-muted/40 hover:bg-muted text-foreground"
358	          } disabled:opacity-60`}
359	        >
360	          {nearbyLoading ? (
361	            <svg className="h-4 w-4 animate-spin shrink-0" viewBox="0 0 24 24" fill="none">
362	              <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3" strokeDasharray="31.4" strokeDashoffset="10" strokeLinecap="round"/>
363	            </svg>
364	          ) : (
365	            <Navigation className="h-4 w-4 shrink-0" />
366	          )}
367	          <span className="flex-1 text-left">
368	            {nearbyMode ? `Netoliese (${NEARBY_KM} km) ✕` : "Ieškoti netoliese"}
369	          </span>
370	        </button>
371	        {nearbyError && (
372	          <p className="mt-1.5 text-xs text-destructive">{nearbyError}</p>
373	        )}
374	      </div>
375	
376	      {/* Sport filter (icon buttons) */}
377	      {sportFilterControls}
378	
379	      {/* City — multi-select, sorted by court count */}
380	      <div>
381	        <div className="flex items-center justify-between mb-2">
382	          <Label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">{t("courts.filters.city")}</Label>
383	          {selectedCities.size > 0 && (
384	            <button
385	              onClick={() => setSelectedCities(new Set())}
386	              className="text-[10px] font-medium text-primary hover:underline"
387	            >
388	              Valyti ({selectedCities.size})
389	            </button>
390	          )}
391	        </div>
392	        <div className="space-y-1">
393	          {(cityExpanded ? sortedCities : sortedCities.filter((c, i) => i < 5 || selectedCities.has(c))).map(c => {
394	            const active = selectedCities.has(c);
395	            const count = cityCounts[c] ?? 0;
396	            return (
397	              <button
398	                key={c}
399	                onClick={() => toggleCity(c)}
400	                className={`w-full flex items-center gap-2.5 px-2 py-1.5 rounded-lg transition-all text-left text-sm ${
401	                  active ? "bg-primary/10 hover:bg-primary/15" : "opacity-60 hover:opacity-90 hover:bg-muted/40"
402	                }`}
403	              >
404	                <div
405	                  className={`w-4 h-4 rounded border-2 flex items-center justify-center shrink-0 transition-all ${
406	                    active ? "bg-primary border-primary" : "border-muted-foreground/40 bg-transparent"
407	                  }`}
408	                >
409	                  {active && (
410	                    <svg className="w-2.5 h-2.5 text-white" viewBox="0 0 10 10" fill="none">
411	                      <path d="M1.5 5L4 7.5L8.5 2.5" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/>
412	                    </svg>
413	                  )}
414	                </div>
415	                <span className={`flex-1 font-medium transition-colors ${active ? "text-foreground" : "text-muted-foreground"}`}>
416	                  {c}
417	                </span>
418	                <span className={`text-xs tabular-nums ${active ? "text-muted-foreground" : "text-muted-foreground/50"}`}>
419	                  {count}
420	                </span>
421	              </button>
422	            );
423	          })}
424	        </div>
425	        {sortedCities.length > 5 && (
426	          <button
427	            onClick={() => setCityExpanded(v => !v)}
428	            className="mt-1 text-[11px] font-medium text-primary hover:underline flex items-center gap-1"
429	          >
430	            {cityExpanded
431	              ? "Rodyti mažiau ↑"
432	              : `Rodyti daugiau (${sortedCities.length - 5}) ↓`}
433	          </button>
434	        )}
435	      </div>
436	
437	      {/* Search */}
438	      <div>
439	        <Label htmlFor="search" className="mb-1.5 block text-xs font-medium text-muted-foreground uppercase tracking-wider">{t("courts.filters.search")}</Label>
440	        <div className="relative">
441	          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
442	          <Input
443	            id="search"
444	            placeholder={t("courts.filters.searchPlaceholder")}
445	            className="pl-9"
446	            value={search}
447	            onChange={(e) => setSearch(e.target.value)}
448	          />
449	        </div>
450	      </div>
451	
452	      {/* Indoor / Outdoor */}
453	      <div>
454	        <Label className="mb-1.5 block text-xs font-medium text-muted-foreground uppercase tracking-wider">{t("courts.filters.location")}</Label>
455	        <div className="flex rounded-md border overflow-hidden">
456	          {(["all", "indoor", "outdoor"] as const).map(opt => (
457	            <button
458	              key={opt}
459	              onClick={() => setIsIndoorFilter(opt)}
460	              className={`flex-1 text-xs py-2.5 font-medium transition-colors ${isIndoorFilter === opt ? "bg-primary text-primary-foreground" : "bg-background hover:bg-muted text-muted-foreground"}`}
461	            >
462	              {opt === "all" ? t("courts.filters.all") : opt === "indoor" ? t("courts.filters.indoor") : t("courts.filters.outdoor")}
463	            </button>
464	          ))}
465	        </div>
466	      </div>
467	
468	      {/* Surface */}
469	      <div>
470	        <Label className="mb-1.5 block text-xs font-medium text-muted-foreground uppercase tracking-wider">{t("courts.filters.surface")}</Label>
471	        <Select value={surface} onValueChange={setSurface}>
472	          <SelectTrigger>
473	            <SelectValue placeholder={t("courts.filters.allSurfaces")} />
474	          </SelectTrigger>
475	          <SelectContent>
476	            <SelectItem value="all">{t("courts.filters.allSurfaces")}</SelectItem>
477	            {surfaceKeys.map(key => (
478	              <SelectItem key={key} value={key}>{t(`surfaces.${key}`)}</SelectItem>
479	            ))}
480	          </SelectContent>
481	        </Select>
482	      </div>
483	
484	      {/* Max Price */}
485	      <div>
486	        <Label className="mb-1.5 flex justify-between text-xs font-medium text-muted-foreground uppercase tracking-wider">
487	          <span>{t("courts.filters.maxPrice")}</span>
488	          <span className="text-primary font-bold normal-case text-sm">{maxPrice}€</span>
489	        </Label>
490	        <Slider
491	          value={[maxPrice]}
492	          onValueChange={(v) => setMaxPrice(v[0])}
493	          max={100}
494	          step={5}
