1	import { useState, useRef } from "react";
2	import { useLocation } from "wouter";
3	import { Layout } from "@/components/layout";
4	import { EmptyState } from "@/components/empty-state";
5	import { useListBookings, useCancelBooking, useCreateReview, getListBookingsQueryKey, customFetch, useGetRefundPreview, getGetRefundPreviewQueryKey } from "@workspace/api-client-react";
6	import { format, parseISO, isFuture, isToday } from "date-fns";
7	import { lt } from "date-fns/locale";
8	import { Badge } from "@/components/ui/badge";
9	import { Button } from "@/components/ui/button";
10	import { Skeleton } from "@/components/ui/skeleton";
11	import { useQueryClient } from "@tanstack/react-query";
12	import { useToast } from "@/hooks/use-toast";
13	import { CheckCircle2, Clock, XCircle, Star, MapPin, Calendar, ChevronRight, Image as ImageIcon, X, Loader2, Upload, Users } from "lucide-react";
14	import {
15	  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter,
16	} from "@/components/ui/dialog";
17	import { Textarea } from "@/components/ui/textarea";
18	import { Label } from "@/components/ui/label";
19	import {
20	  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
21	} from "@/components/ui/select";
22	import { useT } from "@/lib/i18n";
23	
24	type SortKey = "dateAsc" | "dateDesc" | "createdDesc" | "createdAsc";
25	
26	const BASE_URL = import.meta.env.BASE_URL.replace(/\/$/, "");
27	const API_URL = `${BASE_URL}/api`;
28	
29	function StarPicker({ value, onChange }: { value: number; onChange: (v: number) => void }) {
30	  const [hovered, setHovered] = useState(0);
31	  return (
32	    <div className="flex gap-2 justify-center">
33	      {[1, 2, 3, 4, 5].map((star) => (
34	        <button
35	          key={star}
36	          type="button"
37	          onMouseEnter={() => setHovered(star)}
38	          onMouseLeave={() => setHovered(0)}
39	          onClick={() => onChange(star)}
40	          className="focus:outline-none transition-transform hover:scale-110"
41	        >
42	          <Star
43	            className={`h-9 w-9 transition-colors ${
44	              star <= (hovered || value) ? "fill-yellow-400 text-yellow-400" : "text-muted-foreground/30"
45	            }`}
46	          />
47	        </button>
48	      ))}
49	    </div>
50	  );
51	}
52	
53	interface RateDialogProps {
54	  open: boolean;
55	  onClose: () => void;
56	  booking: { id: number; courtName?: string; courtId: number; customerName: string } | null;
57	}
58	
59	function RateDialog({ open, onClose, booking }: RateDialogProps) {
60	  const t = useT();
61	  const [rating, setRating] = useState(0);
62	  const [reviewText, setReviewText] = useState("");
63	  const [photos, setPhotos] = useState<string[]>([]);
64	  const [uploading, setUploading] = useState(false);
65	  const fileInputRef = useRef<HTMLInputElement>(null);
66	  const createReview = useCreateReview();
67	  const { toast } = useToast();
68	
69	  const ratingLabels = ["", t("rating.1"), t("rating.2"), t("rating.3"), t("rating.4"), t("rating.5")];
70	
71	  const handlePhotoUpload = async (files: FileList) => {
72	    const remaining = 3 - photos.length;
73	    if (remaining <= 0) return;
74	    const toUpload = Array.from(files).slice(0, remaining);
75	    setUploading(true);
76	    try {
77	      for (const file of toUpload) {
78	        const fd = new FormData();
79	        fd.append("image", file);
80	        const res = await fetch(`${API_URL}/upload/court-image`, { method: "POST", body: fd });
81	        if (res.ok) {
82	          const data = await res.json();
83	          setPhotos(prev => [...prev, data.path].slice(0, 3));
84	        }
85	      }
86	    } catch {
87	      toast({ title: "Klaida", description: "Nepavyko įkelti nuotraukos", variant: "destructive" });
88	    } finally {
89	      setUploading(false);
90	    }
91	  };
92	
93	  const handleSubmit = async () => {
94	    if (!booking || rating === 0) return;
95	    try {
96	      await createReview.mutateAsync({
97	        id: booking.courtId,
98	        data: {
99	          bookingId: booking.id,
100	          rating,
101	          reviewText: reviewText.trim() || undefined,
102	          reviewerName: booking.customerName,
103	          photos: photos.length > 0 ? photos : undefined,
104	        },
105	      });
106	      toast({ title: "Ačiū už atsiliepimą! 🌟", description: "Jūsų įvertinimas išsaugotas." });
107	      setRating(0);
108	      setReviewText("");
109	      setPhotos([]);
110	      onClose();
111	    } catch (error: any) {
112	      const msg = error?.response?.data?.error || "Nepavyko išsaugoti atsiliepimo.";
113	      toast({ title: "Klaida", description: msg, variant: "destructive" });
114	    }
115	  };
116	
117	  return (
118	    <Dialog open={open} onOpenChange={(o) => { if (!o) onClose(); }}>
119	      <DialogContent className="sm:max-w-md">
120	        <DialogHeader>
121	          <DialogTitle>{t("bookings.rateDialog.title")}</DialogTitle>
122	          <DialogDescription>{booking?.courtName || `#${booking?.courtId}`}</DialogDescription>
123	        </DialogHeader>
124	
125	        <div className="space-y-5 py-4">
126	          <div className="text-center">
127	            <StarPicker value={rating} onChange={setRating} />
128	            {rating > 0 && <p className="text-sm font-medium mt-2 text-primary">{ratingLabels[rating]}</p>}
129	          </div>
130	
131	          <div className="space-y-2">
132	            <Label>{t("bookings.rateDialog.commentLabel")}</Label>
133	            <Textarea
134	              placeholder={t("bookings.rateDialog.commentPlaceholder")}
135	              value={reviewText}
136	              onChange={(e) => setReviewText(e.target.value)}
137	              rows={3}
138	            />
139	          </div>
140	
141	          {/* Photo upload */}
142	          <div className="space-y-2">
143	            <Label className="flex items-center gap-1.5">
144	              <ImageIcon className="w-3.5 h-3.5" /> Nuotraukos (iki 3)
145	            </Label>
146	            <div className="flex gap-2 flex-wrap">
147	              {photos.map((p, i) => (
148	                <div key={i} className="relative w-20 h-20 rounded-lg overflow-hidden border border-border group">
149	                  <img src={`${BASE_URL}/${p}`} alt="" className="w-full h-full object-cover" />
150	                  <button
151	                    type="button"
152	                    onClick={() => setPhotos(prev => prev.filter((_, idx) => idx !== i))}
153	                    className="absolute top-0.5 right-0.5 bg-black/60 text-white rounded-full p-0.5 opacity-0 group-hover:opacity-100 transition-opacity"
154	                  >
155	                    <X className="w-3 h-3" />
156	                  </button>
157	                </div>
158	              ))}
159	              {photos.length < 3 && (
160	                <button
161	                  type="button"
162	                  onClick={() => fileInputRef.current?.click()}
163	                  disabled={uploading}
164	                  className="w-20 h-20 rounded-lg border-2 border-dashed border-border flex flex-col items-center justify-center gap-1 text-muted-foreground hover:border-primary hover:text-primary transition-colors"
165	                >
166	                  {uploading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Upload className="w-5 h-5" />}
167	                  <span className="text-[10px]">{uploading ? "Keliama..." : "Pridėti"}</span>
168	                </button>
169	              )}
170	            </div>
171	            <input
172	              ref={fileInputRef}
173	              type="file"
174	              accept="image/*"
175	              multiple
176	              className="hidden"
177	              onChange={e => { if (e.target.files?.length) handlePhotoUpload(e.target.files); e.target.value = ""; }}
178	            />
179	          </div>
180	        </div>
181	
182	        <DialogFooter>
183	          <Button variant="outline" onClick={onClose}>{t("bookings.cancel")}</Button>
184	          <Button onClick={handleSubmit} disabled={rating === 0 || createReview.isPending}>
185	            {createReview.isPending ? "..." : t("bookings.rateDialog.submit")}
186	          </Button>
187	        </DialogFooter>
188	      </DialogContent>
189	    </Dialog>
190	  );
191	}
192	
193	type BookingItem = {
194	  id: number;
195	  courtId: number;
196	  courtName?: string;
197	  customerName: string;
198	  customerEmail: string;
199	  date: Date;
200	  startTime: string;
201	  endTime: string;
202	  totalPrice: number;
203	  status: "pending" | "confirmed" | "cancelled" | "awaiting_players";
204	  createdAt?: string;
205	  refundAmount?: number;
206	  isSplit?: boolean;
207	  totalSlots?: number;
208	  pricePerSlot?: number;
209	  splitInviteToken?: string | null;
210	};
211	
212	function CancelBookingDialog({
213	  bookingId,
214	  onClose,
215	  onConfirmed,
216	}: {
217	  bookingId: number | null;
218	  onClose: () => void;
219	  onConfirmed: (id: number) => Promise<void>;
220	}) {
221	  const t = useT();
222	  const open = bookingId !== null;
223	  const { data: preview, isLoading } = useGetRefundPreview(bookingId ?? 0, {
224	    query: { queryKey: getGetRefundPreviewQueryKey(bookingId ?? 0), enabled: open },
225	  });
226	  const [submitting, setSubmitting] = useState(false);
227	
228	  const hours = preview?.hoursBeforeStart ?? 0;
229	  const refundEur = preview?.refundAmount ?? 0;
230	  const isFreeSlot = (preview?.totalPrice ?? 0) <= 0;
231	  const isLate = !preview?.refundable;
232	  const tierKey = (preview?.refundPercent ?? 0) >= 80
233	    ? "bookings.cancel.tier80"
234	    : (preview?.refundPercent ?? 0) >= 50
235	      ? "bookings.cancel.tier50"
236	      : "bookings.cancel.tier0";
237	
238	  const handleConfirm = async () => {
239	    if (!bookingId) return;
240	    setSubmitting(true);
241	    try {
242	      await onConfirmed(bookingId);
243	      onClose();
244	    } finally {
245	      setSubmitting(false);
246	    }
247	  };
248	
249	  return (
250	    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
251	      <DialogContent className="max-w-md">
252	        <DialogHeader>
253	          <DialogTitle>{t("bookings.cancel.title")}</DialogTitle>
254	          <DialogDescription>
255	            {isLoading || !preview
256	              ? t("bookings.cancel.loading")
257	              : preview.canCancel
258	              ? isFreeSlot
259	                ? t("bookings.cancel.freeSlot").replace("{hours}", hours.toFixed(1))
260	                : t(tierKey)
261	              : preview.reason ?? t("bookings.cancel.notAllowed")}
262	          </DialogDescription>
263	        </DialogHeader>
264	
265	        {preview && preview.canCancel && !isFreeSlot && (
266	          <div className="rounded-lg border bg-muted/40 p-3 text-sm space-y-1.5">
267	            <div className="flex justify-between">
268	              <span className="text-muted-foreground">{t("bookings.cancel.totalPaid")}</span>
269	              <span className="font-medium">€{preview.totalPrice.toFixed(2)}</span>
270	            </div>
271	            <div className="flex justify-between">
272	              <span className="text-muted-foreground">{t("bookings.cancel.refundPercent")}</span>
273	              <span className="font-medium">{preview.refundPercent}%</span>
274	            </div>
275	            <div className="flex justify-between border-t pt-1.5 mt-1.5">
276	              <span className="font-semibold">{t("bookings.cancel.refundAmount")}</span>
277	              <span className={`font-bold ${isLate ? "text-destructive" : "text-green-600 dark:text-green-400"}`}>
278	                €{refundEur.toFixed(2)}
279	              </span>
280	            </div>
281	          </div>
282	        )}
283	
284	        <p className="text-xs text-muted-foreground">{t("bookings.cancel.policyShort")}</p>
285	
286	        <DialogFooter className="gap-2">
287	          <Button variant="outline" onClick={onClose} disabled={submitting}>
288	            {t("bookings.cancel.keep")}
289	          </Button>
290	          <Button
291	            variant="destructive"
292	            onClick={handleConfirm}
293	            disabled={submitting || !preview?.canCancel}
294	          >
295	            {submitting ? <Loader2 className="w-4 h-4 mr-1.5 animate-spin" /> : null}
296	            {t("bookings.cancel.confirm")}
297	          </Button>
298	        </DialogFooter>
299	      </DialogContent>
300	    </Dialog>
301	  );
302	}
303	
304	function getStatusBadge(status: string, t: ReturnType<typeof useT>, refundAmount?: number) {
305	  switch (status) {
306	    case "confirmed":
307	      return <Badge className="bg-green-500 hover:bg-green-600 text-white text-xs"><CheckCircle2 className="w-3 h-3 mr-1" />{t("bookings.status.confirmed")}</Badge>;
308	    case "pending":
309	      return <Badge variant="secondary" className="bg-yellow-500/20 text-yellow-700 dark:text-yellow-400 text-xs"><Clock className="w-3 h-3 mr-1" />{t("bookings.status.pending")}</Badge>;
310	    case "awaiting_players":
311	      return <Badge variant="secondary" className="bg-blue-500/20 text-blue-700 dark:text-blue-400 text-xs"><Users className="w-3 h-3 mr-1" />Laukiama žaidėjų</Badge>;
312	    case "cancelled": {
313	      const r = Number(refundAmount ?? 0);
314	      const label = r > 0
315	        ? `${t("bookings.status.cancelled")} · ${t("bookings.cancel.refunded")} €${r.toFixed(2)}`
316	        : `${t("bookings.status.cancelled")} · ${t("bookings.cancel.noRefund")}`;
317	      return <Badge variant="destructive" className="text-xs"><XCircle className="w-3 h-3 mr-1" />{label}</Badge>;
318	    }
319	    default:
320	      return <Badge variant="outline" className="text-xs">{status}</Badge>;
321	  }
322	}
323	
324	function BookingCard({
325	  booking,
326	  isUpcoming,
327	  onRate,
328	  onCancel,
329	  cancelling,
330	}: {
331	  booking: BookingItem;
332	  isUpcoming: boolean;
333	  onRate: () => void;
334	  onCancel: () => void;
335	  cancelling: boolean;
336	}) {
337	  const t = useT();
338	  const [, setLocation] = useLocation();
339	
340	  const dateLabel = format(booking.date, "yyyy-MM-dd");
341	  const dayLabel = format(booking.date, "EEEE", { locale: lt });
342	  const createdLabel = booking.createdAt
343	    ? format(new Date(booking.createdAt), "yyyy-MM-dd HH:mm")
344	    : null;
345	
346	  return (
347	    <div
348	      className="bg-card border rounded-xl p-4 space-y-3 cursor-pointer hover:border-primary/40 hover:shadow-sm transition-all group"
349	      onClick={() => setLocation(`/bookings/${booking.id}`)}
350	    >
351	      {/* Top row: court name + status */}
352	      <div className="flex items-start justify-between gap-2">
353	        <div className="min-w-0">
354	          <p className="font-semibold text-sm group-hover:text-primary transition-colors truncate">
355	            {booking.courtName || `Kortas #${booking.courtId}`}
356	          </p>
357	        </div>
358	        <div className="flex items-center gap-1.5 shrink-0">
359	          {getStatusBadge(booking.status, t, booking.refundAmount)}
360	          <ChevronRight className="w-4 h-4 text-muted-foreground/50" />
361	        </div>
362	      </div>
363	
364	      {/* Date/time + price row */}
365	      <div className="flex items-center gap-4 text-sm text-muted-foreground">
366	        <span className="flex items-center gap-1.5">
367	          <Calendar className="w-3.5 h-3.5" />
368	          <span className="capitalize">{dayLabel},</span>
369	          <span>{dateLabel}</span>
370	        </span>
371	        <span className="flex items-center gap-1">
372	          <Clock className="w-3.5 h-3.5" />
373	          {booking.startTime} – {booking.endTime}
374	        </span>
375	      </div>
376	      {createdLabel && (
377	        <div className="text-xs text-muted-foreground/70">
378	          {t("bookings.bookedAt")}: {createdLabel}
379	        </div>
380	      )}
381	
382	      {/* Split badge */}
383	      {booking.isSplit && (
384	        <div className="flex items-center gap-1.5 text-xs text-blue-700 dark:text-blue-400">
385	          <Users className="w-3.5 h-3.5" />
386	          <span>Bendras mokėjimas · jūsų dalis {booking.pricePerSlot != null ? `€${Number(booking.pricePerSlot).toFixed(2)}` : ""} iš {booking.totalSlots ?? "?"} žaidėjų</span>
387	        </div>
388	      )}
389	
390	      {/* Price + actions */}
391	      <div className="flex items-center justify-between pt-1 border-t border-border/50">
392	        <div className="flex flex-col">
393	          <span className="text-sm font-semibold">
394	            {booking.isSplit && booking.pricePerSlot != null
395	              ? (booking.pricePerSlot > 0 ? `€${Number(booking.pricePerSlot).toFixed(2)}` : "Nemokama")
396	              : (booking.totalPrice > 0 ? `€${Number(booking.totalPrice).toFixed(2)}` : "Nemokama")}
397	          </span>
398	          {booking.isSplit && booking.pricePerSlot != null && (
399	            <span className="text-[10px] text-muted-foreground">iš €{Number(booking.totalPrice).toFixed(2)} viso</span>
400	          )}
401	        </div>
402	        <div className="flex gap-2" onClick={e => e.stopPropagation()}>
403	          {!isUpcoming && booking.status === "confirmed" && (
404	            <Button
405	              variant="outline"
406	              size="sm"
407	              className="text-yellow-600 hover:text-yellow-700 border-yellow-200 hover:bg-yellow-50 dark:border-yellow-900 dark:hover:bg-yellow-900/20 gap-1 h-8 text-xs"
408	              onClick={onRate}
409	            >
410	              <Star className="h-3 w-3" />
411	              {t("bookings.rate")}
412	            </Button>
413	          )}
414	          {isUpcoming && (booking.status === "confirmed" || booking.status === "awaiting_players") && (
415	            <Button
416	              variant="ghost"
417	              size="sm"
418	              className="text-destructive hover:text-destructive hover:bg-destructive/10 h-8 text-xs"
419	              onClick={onCancel}
420	              disabled={cancelling}
421	            >
422	              {t("bookings.cancel")}
423	            </Button>
424	          )}
425	        </div>
426	      </div>
427	    </div>
428	  );
429	}
