431	export default function Bookings() {
432	  const t = useT();
433	  const [tab, setTab] = useState<"upcoming" | "past">("upcoming");
434	  const [sortKey, setSortKey] = useState<SortKey>("dateAsc");
435	  const [ratingBooking, setRatingBooking] = useState<{
436	    id: number; courtName?: string; courtId: number; customerName: string;
437	  } | null>(null);
438	  const [cancelTargetId, setCancelTargetId] = useState<number | null>(null);
439	
440	  const { data: bookings, isLoading } = useListBookings({});
441	  const cancelBooking = useCancelBooking();
442	  const queryClient = useQueryClient();
443	  const { toast } = useToast();
444	
445	  const handleCancelConfirmed = async (id: number) => {
446	    try {
447	      const result = await cancelBooking.mutateAsync({ id });
448	      const refunded = Number((result as any)?.refundAmount ?? 0);
449	      toast({
450	        title: t("bookings.status.cancelled"),
451	        description: refunded > 0
452	          ? t("bookings.cancel.toastRefunded").replace("{amount}", refunded.toFixed(2))
453	          : t("bookings.cancel.toastNoRefund"),
454	      });
455	      queryClient.invalidateQueries({ queryKey: getListBookingsQueryKey() });
456	      queryClient.invalidateQueries({ queryKey: ["court-activity"] });
457	      queryClient.invalidateQueries({
458	        predicate: (q) => Array.isArray(q.queryKey) && q.queryKey.some(
459	          (k) => typeof k === "string" && k.includes("/availability"),
460	        ),
461	      });
462	    } catch {
463	      toast({ title: "Klaida", variant: "destructive" });
464	    }
465	  };
466	
467	  const today = new Date();
468	  today.setHours(0, 0, 0, 0);
469	
470	  const sorted = (bookings ?? []).slice().sort((a, b) => {
471	    if (sortKey === "createdDesc" || sortKey === "createdAsc") {
472	      const ca = a.createdAt ? new Date(a.createdAt).getTime() : 0;
473	      const cb = b.createdAt ? new Date(b.createdAt).getTime() : 0;
474	      return sortKey === "createdDesc" ? cb - ca : ca - cb;
475	    }
476	    const da = new Date(a.date).getTime();
477	    const db2 = new Date(b.date).getTime();
478	    if (da !== db2) return sortKey === "dateAsc" ? da - db2 : db2 - da;
479	    return sortKey === "dateAsc"
480	      ? a.startTime.localeCompare(b.startTime)
481	      : b.startTime.localeCompare(a.startTime);
482	  });
483	
484	  const localCancelledIds: number[] = (() => {
485	    try { return JSON.parse(sessionStorage.getItem("cancelledBookingIds") ?? "[]"); } catch { return []; }
486	  })();
487	  const startMs = (b: typeof sorted[number]) => {
488	    const dt = new Date(b.date);
489	    const [hh, mm] = (b.startTime ?? "00:00").split(":").map(Number);
490	    dt.setHours(hh || 0, mm || 0, 0, 0);
491	    return dt.getTime();
492	  };
493	  const nowMs = Date.now();
494	  const upcomingBookings = sorted.filter(b => {
495	    return startMs(b) > nowMs && b.status !== "cancelled" && !localCancelledIds.includes(b.id);
496	  });
497	
498	  const pastBookings = sorted.filter(b => {
499	    return startMs(b) <= nowMs || b.status === "cancelled";
500	  });
501	
502	  const displayed = tab === "upcoming" ? upcomingBookings : pastBookings;
503	
504	  return (
505	    <Layout>
506	      <div className="container mx-auto px-4 py-8 max-w-2xl">
507	        <div className="mb-6">
508	          <h1 className="text-2xl font-bold tracking-tight">{t("bookings.title")}</h1>
509	          <p className="text-muted-foreground mt-1 text-sm">{t("bookings.subtitle")}</p>
510	        </div>
511	
512	        {/* Tabs + Sort */}
513	        <div className="flex items-center justify-between gap-3 mb-6 flex-wrap">
514	          <div className="flex bg-muted p-1 rounded-lg w-fit">
515	            <button
516	              onClick={() => setTab("upcoming")}
517	              className={`px-5 py-2 text-sm font-medium rounded-md transition-colors relative ${
518	                tab === "upcoming" ? "bg-background shadow-sm" : "text-muted-foreground hover:text-foreground"
519	              }`}
520	            >
521	              Ateinančios
522	              {upcomingBookings.length > 0 && !isLoading && (
523	                <span className="ml-1.5 inline-flex items-center justify-center w-4 h-4 rounded-full bg-primary text-primary-foreground text-[10px] font-semibold">
524	                  {upcomingBookings.length}
525	                </span>
526	              )}
527	            </button>
528	            <button
529	              onClick={() => setTab("past")}
530	              className={`px-5 py-2 text-sm font-medium rounded-md transition-colors ${
531	                tab === "past" ? "bg-background shadow-sm" : "text-muted-foreground hover:text-foreground"
532	              }`}
533	            >
534	              Praeitos
535	            </button>
536	          </div>
537	          <Select value={sortKey} onValueChange={(v) => setSortKey(v as SortKey)}>
538	            <SelectTrigger className="h-9 w-auto min-w-[180px] text-sm">
539	              <SelectValue />
540	            </SelectTrigger>
541	            <SelectContent>
542	              <SelectItem value="dateAsc">{t("bookings.sort.dateAsc")}</SelectItem>
543	              <SelectItem value="dateDesc">{t("bookings.sort.dateDesc")}</SelectItem>
544	              <SelectItem value="createdDesc">{t("bookings.sort.createdDesc")}</SelectItem>
545	              <SelectItem value="createdAsc">{t("bookings.sort.createdAsc")}</SelectItem>
546	            </SelectContent>
547	          </Select>
548	        </div>
549	
550	        {/* List */}
551	        <div className="space-y-3">
552	          {isLoading ? (
553	            Array.from({ length: 3 }).map((_, i) => (
554	              <div key={i} className="bg-card border rounded-xl p-4 space-y-3">
555	                <Skeleton className="h-5 w-2/3" />
556	                <Skeleton className="h-4 w-1/2" />
557	                <Skeleton className="h-4 w-1/3" />
558	              </div>
559	            ))
560	          ) : displayed.length === 0 ? (
561	            <EmptyState
562	              icon={<Calendar className="w-10 h-10" />}
563	              title={tab === "upcoming" ? "Nėra ateinančių rezervacijų" : "Nėra praeities rezervacijų"}
564	              description={tab === "upcoming" ? "Rezervuokite aikštelę ir ji pasirodys čia." : "Jūsų praeitos rezervacijos bus rodomos čia."}
565	            />
566	          ) : (
567	            displayed.map((booking) => {
568	              const startDt = new Date(booking.date);
569	              const [sh, sm] = (booking.startTime ?? "00:00").split(":").map(Number);
570	              startDt.setHours(sh || 0, sm || 0, 0, 0);
571	              const isUpcoming = startDt.getTime() > Date.now() && booking.status !== "cancelled";
572	              return (
573	                <BookingCard
574	                  key={booking.id}
575	                  booking={{
576	                    ...booking,
577	                    date: new Date(booking.date),
578	                    refundAmount: Number((booking as any).refundAmount ?? 0),
579	                  }}
580	                  isUpcoming={isUpcoming}
581	                  onRate={() => setRatingBooking({
582	                    id: booking.id,
583	                    courtName: booking.courtName ?? undefined,
584	                    courtId: booking.courtId,
585	                    customerName: booking.customerName,
586	                  })}
587	                  onCancel={() => setCancelTargetId(booking.id)}
588	                  cancelling={cancelBooking.isPending}
589	                />
590	              );
591	            })
592	          )}
593	        </div>
594	      </div>
595	
596	      <RateDialog
597	        open={!!ratingBooking}
598	        onClose={() => setRatingBooking(null)}
599	        booking={ratingBooking}
600	      />
601	
602	      <CancelBookingDialog
603	        bookingId={cancelTargetId}
604	        onClose={() => setCancelTargetId(null)}
605	        onConfirmed={handleCancelConfirmed}
606	      />
607	    </Layout>
608	  );
609	}
